"""Insert measured scalar tables into the experiment README (English working notes).
Input: local summary.json and the successful run records. Output: README.md.
"""
from pathlib import Path
import json,re
p=Path(__file__).resolve().parent
summary=json.loads((p/'summary.json').read_text())
D=json.loads((p/'output/run-001/science/result.json').read_text());R=json.loads((p/'output/run-003/science/result.json').read_text())
rr=summary['ratios'];lines=[]
lines.append(f"R gives a **{rr['width_D_over_R']:.2f} times narrower interval** at **{rr['cold_production_R_over_D']:.2f} times the cold production cost** of D. Including every additional verification check gives a cost ratio of {rr['cold_plus_verification_R_over_D']:.2f}. Both outputs reproduce the accepted RT3 results and all required checks pass.")
lines.append('These are measured postprocessing costs from saved inputs in separate fresh MATLAB processes. No prepared object or field cache crosses between R and D. Operating-system file caches were not flushed. One successful process per trial was measured; the earlier R inventory failure is counted only in the total stage budget.')
lines.append('| Trial / run | Cold production | Additional verification | Production + verification | Monitor wall | Peak RSS | Width |\n|---|---:|---:|---:|---:|---:|---:|')
for kind,num in [('R',3),('D',1)]:
 b=summary['records'][kind]['benchmark'];lines.append(f"| {kind} / {num:03d} | {b['cold_production_seconds']:.3f} s | {b['additional_verification_seconds']:.3f} s | {b['cold_production_plus_verification_seconds']:.3f} s | {b['monitored_wall_seconds']:.3f} s | {b['peak_rss_gib']:.3f} GiB | {b['width']:.12e} |")
lines.append(f"Inside the MATLAB function, production takes R {R['production_seconds']:.3f} s and D {D['production_seconds']:.3f} s, ratio {rr['matlab_production_R_over_D']:.2f}. The additional-verification ratio is {rr['verification_R_over_D']:.2f}; the complete monitored-wall ratio is {rr['monitored_wall_R_over_D']:.2f}. Startup and shutdown affect these ratios differently. The primary result uses the declared cold-production boundary, with the other boundaries shown explicitly.")
lines.append('| Trial | q | J (order 16) | J (order 24, same flux) | J Gram | Interval |\n|---|---:|---:|---:|---:|---|')
for kind,r in [('R',R),('D',D)]:
 a=r['production'];v=r['verification'];lines.append(f"| {kind} | {a['q']:.17g} | {a['J']:.17g} | {v['J24']:.17g} | {a['J_gram']:.17g} | [{a['enclosure'][0]:.16f}, {a['enclosure'][1]:.16f}] |")
lines.append('Sources: [D result](output/run-001/science/result.json), [R result](output/run-003/science/result.json), their monitor.json and launcher.json records; [summary.json](summary.json), [benchmark.csv](benchmark.csv), and [timings.csv](timings.csv) collect the scalars and independent arithmetic.')
lines.append('### Disjoint timing components')
lines.append('| Production component | R seconds | D seconds |\n|---|---:|---:|')
labels={'native_input':'Native input loading','source_input':'Source-block loading and correction addition','coefficient_build':'Closed-form coefficients and unweighted norm checks','source_assembly_other':'Source indexing, metadata and allocation','normalization':'Trial normalization and tails','geometry':'Fitted geometry and mapped points','primary_field':'Order-16 field values','prepare_other':'Preparation bookkeeping','basis':'Stable RT basis','assembly':'Matrix and load assembly','solve':'Condensation, solve, recovery, Gram and traces','solve_other':'Solve bookkeeping','functional':'Pointwise functional','production_output':'Production scalar output','orchestration':'Production orchestration'}
for k,label in labels.items():lines.append(f"| {label} | {R['production_timing'][k]:.6f} | {D['production_timing'][k]:.6f} |")
lines.append(f"| **MATLAB production total** | **{R['production_seconds']:.6f}** | **{D['production_seconds']:.6f}** |")
lines.append('| Additional verification component | R seconds | D seconds |\n|---|---:|---:|')
labels={'field24':'Order-24 field values','functional24':'Order-24 pointwise functional and mapped points','normalization':'Normalization integration checks','areas':'Order-24 fitted areas','other':'Verification-stage bookkeeping','component_audit':'Separate component assembly audit','cache_check':'Fresh batch and key rejection','recheck_functional':'Primary functional after verification','immutability_comparison':'Exact state comparison','verification_output_and_orchestration':'Verification output and orchestration'}
for k,label in labels.items():lines.append(f"| {label} | {R['verification_timing'][k]:.6f} | {D['verification_timing'][k]:.6f} |")
lines.append(f"| **Additional verification total** | **{R['verification_seconds']:.6f}** | **{D['verification_seconds']:.6f}** |")
lines.append('The primary field cache in R already existed in v1; v2 preserves that reuse. D now gets the same reuse, and both paths avoid matrix reassembly during the primary pointwise evaluation. Higher-order integration and component assembly audits are separate API calls; this benchmark includes the primary component audit and the required higher-order pointwise comparison.')
lines.append('### Startup, output and wall reconciliation')
lines.append('| Wall component | R seconds | D seconds |\n|---|---:|---:|')
for label,key,from_report in [('Launch through MATLAB entry','startup_to_entry_seconds',True),('MATLAB production','production_seconds',True),('Additional verification','verification_seconds',True),('Final report construction','function_postverification_orchestration_seconds',False),('Final report output','matlab_finalization_output_seconds',False),('MATLAB shutdown and monitor tail','shutdown_and_monitor_tail_seconds',False)]:
 vals=[]
 for kind,r in [('R',R),('D',D)]:vals.append(r[key] if from_report else summary['records'][kind]['wall_reconciliation'][key])
 lines.append(f'| {label} | {vals[0]:.6f} | {vals[1]:.6f} |')
for label,key in [('Sum minus wrapper wall','reconciliation_error_seconds'),('Wrapper minus monitor wall (already within launch/tail)','wrapper_minus_monitor_seconds')]:
 vals=[summary['records'][k]['wall_reconciliation'][key] for k in ['R','D']];lines.append(f'| {label} | {vals[0]:.6f} | {vals[1]:.6f} |')
lines.append('Disjoint production and verification sums each equal their enclosing MATLAB timer. The independent clock-to-wrapper discrepancies are below 0.016 s, within max(0.1 s, 1%). The wrapper/monitor difference is shown as a decomposition, not added again. Cold-production clock readings differ from entry-to-ready timer sums by 0.013 s for R and 0.008 s for D; both are included in the reported clock reconciliation.')
lines.append('### Required checks')
lines.append('| Comparison | R | D | Acceptance |\n|---|---:|---:|---|')
for label,key,tol in [('q versus stored RT3, relative','baseline_q_relative','<=1e-12'),('Width versus stored RT3, relative','baseline_width_relative','<=0.005'),('J versus stored RT3, scaled','baseline_J_scaled','<=0.01'),('Gram versus pointwise J, scaled','gram_scaled','<0.01'),('Endpoint difference versus width formula, absolute','width_formula_difference','<=1e-13')]:
 lines.append(f"| {label} | {abs(R['production'][key]):.6e} | {abs(D['production'][key]):.6e} | {tol}; pass |")
lines.append(f"| Order-24 versus order-16 J, scaled | {R['verification']['scaled_quadrature']:.6e} | {D['verification']['scaled_quadrature']:.6e} | <0.01; pass |")
lines.append(f"| qJ-1 | {R['production']['qJ_minus_one']:.9e} | {D['production']['qJ_minus_one']:.9e} | positive; pass |")
lines.append('Both positive Gram denominators, both kappa inequalities and containment of mu_BIE=2.428728670022710 pass. The independent Python postprocessor recomputes both endpoints and both widths and agrees within 1.81e-15; full scalar inputs and kappa values are in the result files. Normal-trace errors are 8.24e-14; global solve residuals are below 1.23e-15 and cell residuals below 1.83e-12.')
lines.append('The maximum relative inclusion-area error at order 16 is 2.66e-15 and at order 24 is 8.58e-16; maximum cell-area error is 1.56e-14, all below 1e-12. D enforced the order-16 assertion; R additionally retained the three primary area scalars for the identical geometry. R reproduces theta to relative 1.83e-16, its unweighted norm to 4.45e-16, and its two numerator formulas agree to 3.82e-15. The R normalization x-order change is -2.665e-12 in theta, and the y-order change is 4.44e-16. The exterior mass bound relative to the whole-strip trial mass is below 1.83e-11 (<1e-10).')
lines.append('For each trial, q, J, the interval and all flux coefficients are exactly unchanged after verification. R’s reconstruction coefficients are also compared exactly; D uses the same immutable prepared native coefficient arrays throughout. A fresh evaluation at 32 template points across 13 cells (416 values) matches its cache with relative difference zero. All six incompatible-key tests reject: phase, quadrature, trial, geometry, source level and input directory. There is no whole-field recomputation for this cache test.')
lines.append('| Field operation, each trial | Batches | Values |\n|---|---:|---:|\n| Primary evaluations | 408 | 44,225,536 |\n| Assembly cache hits | 408 | 44,225,536 reused |\n| Production functional cache hits | 408 | 44,225,536 reused |\n| Separate audit cache hits | 408 | 44,225,536 reused |\n| Post-verification functional cache hits | 408 | 44,225,536 reused |\n| New higher-order evaluations | 408 | 99,507,456 |')
lines.append('### Interpretation and remaining cost boundary')
lines.append('The reconstructed trial retains its narrower interval. Primary field evaluation costs 119.02 s for R and 2.69 s for D; assembly, solve and primary functional together cost 8.87 s and 8.63 s. Separating verification makes this difference explicit. The full checked run favors D more strongly than the production-only comparison because new order-24 R field values cost 264.28 s. The result quantifies this tradeoff for the existing control trial and original RT3 mesh; no new refinement or flux-floor claim is added.')
lines.append(f"Total monitored compute, including the failed inventory run, is {summary['total_monitored_compute_seconds']:.3f} s ({summary['total_monitored_compute_seconds']/60:.3f} min), below the shared 30/40-minute limits. Maximum process-tree RSS is {summary['maximum_peak_rss_gib']:.3f} GiB, below 3 GiB. No field caches or flux arrays are retained on disk. Upstream FEM frequency-search time and the minimal ordinary source-generation time remain unmeasured here; see the ledger below.")
s=(p/'README.md').read_text();s=s.replace('TODO: measured D pilot, then R; required checks, upstream ledger and cost comparison.','\n\n'.join(lines));s=re.sub(r'(?m)(^\|[^\n]*\|)\n\n(?=\|)',r'\1\n',s);(p/'README.md').write_text(s)
